import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, texture, uv, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  root.name = 'journal-card-2';

  const timelines = [];
  const resources = [];
  let disposed = false;

  const width = 3.2;
  const height = 2.0;
  const frame = 0.035;

  const backdropGeometry = new PlaneGeometry(width + 0.12, height + 0.12);
  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = vec3(0.043, 0.043, 0.063);

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -0.045;
  backdrop.name = 'journal-card-2-backplate';
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const cardGeometry = new PlaneGeometry(width, height);
  const cardMaterial = new MeshBasicNodeMaterial();

  const v = uv().y;
  const engineeredGradient = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, v)
  );

  cardMaterial.colorNode = engineeredGradient;

  const card = new Mesh(cardGeometry, cardMaterial);
  card.name = 'journal-card-2-grain-surface';
  card.position.z = 0;
  card.renderOrder = 1;
  root.add(card);
  resources.push(cardGeometry, cardMaterial);

  const accentMaterial = new MeshBasicNodeMaterial();
  accentMaterial.colorNode = vec3(1.0, 0.165, 0.22);
  resources.push(accentMaterial);

  const accentGeometryHorizontal = new PlaneGeometry(width * 0.22, frame);
  const accentGeometryVertical = new PlaneGeometry(frame, height * 0.22);
  resources.push(accentGeometryHorizontal, accentGeometryVertical);

  const accentTop = new Mesh(accentGeometryHorizontal, accentMaterial);
  accentTop.position.set(-width * 0.37, height * 0.5 - frame * 0.5, 0.025);

  const accentBottom = new Mesh(accentGeometryHorizontal, accentMaterial);
  accentBottom.position.set(width * 0.37, -height * 0.5 + frame * 0.5, 0.025);

  const accentLeft = new Mesh(accentGeometryVertical, accentMaterial);
  accentLeft.position.set(-width * 0.5 + frame * 0.5, height * 0.37, 0.025);

  const accentRight = new Mesh(accentGeometryVertical, accentMaterial);
  accentRight.position.set(width * 0.5 - frame * 0.5, -height * 0.37, 0.025);

  root.add(accentTop, accentBottom, accentLeft, accentRight);

  const imageUrl = config?.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((loadedTexture) => {
      if (disposed || !loadedTexture) return;

      loadedTexture.colorSpace = ctx.THREE.SRGBColorSpace;
      loadedTexture.wrapS = ctx.THREE.ClampToEdgeWrapping;
      loadedTexture.wrapT = ctx.THREE.ClampToEdgeWrapping;

      // The declared atlas region occupies the complete 512x320 source rect.
      loadedTexture.repeat.set(1, 1);
      loadedTexture.offset.set(0, 0);
      loadedTexture.needsUpdate = true;

      cardMaterial.colorNode = mix(
        engineeredGradient,
        engineeredGradient.mul(texture(loadedTexture).rgb),
        0.18
      );
      cardMaterial.needsUpdate = true;
      resources.push(loadedTexture);
    }).catch(() => {});
  }

  root.onBeforeRender = (_renderer, _scene, camera) => {
    if (!disposed && camera) {
      root.quaternion.copy(camera.quaternion);
    }
  };

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    root.onBeforeRender = null;

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }
    timelines.length = 0;

    for (const resource of resources) {
      if (resource?.dispose) resource.dispose();
    }
    resources.length = 0;
  };

  return root;
}
